def generate_candidates(
    ell: int, m: int
) -> list[tuple[list[tuple[int, int]], list[tuple[int, int]]]]:
    """Generate candidate (A_terms, B_terms) pairs for given lattice dimensions.

    This is the function that gets evolved by the LLM. The initial version
    uses algebraic heuristics based on known good code patterns.

    Args:
        ell: Cyclic group order for x.
        m: Cyclic group order for y.

    Returns:
        List of (A_terms, B_terms) pairs to evaluate.
    """
    candidates = []
    seen = set()

    def _add(a_terms, b_terms):
        """Add candidate if not a duplicate."""
        key = (tuple(sorted(a_terms)), tuple(sorted(b_terms)))
        if key not in seen:
            seen.add(key)
            candidates.append((list(a_terms), list(b_terms)))

    def _gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def _coprime(a, n):
        return _gcd(a, n) == 1

    # -----------------------------------------------------------------------
    # Strategy 1: Seed-based Generation (Linked Polynomials)
    # This strategy generates pairs where A and B share an underlying structure
    # derived from a "seed" polynomial P(z) = 1 + z^s1 + z^s2.
    # This captures both "Constant-Monomial" codes (high-k) and "Gross" codes.
    # -----------------------------------------------------------------------

    seeds = [
        (1, 2), (1, 3), (2, 3),         # Standard dense polynomials
        (1, 4), (3, 4), (1, 5), (2, 5), # Sparse/Gap polynomials
        (3, 5), (2, 7), (3, 8),         # Larger gaps
    ]
    # Add larger seeds for larger lattices
    if m > 12: seeds.extend([(1, 6), (5, 6), (3, 7)])

    # Identify interesting scaling factors for y (A-side) and x (B-side)
    # We want factors k such that y^k generates a subgroup or permutes the group.
    ka_vals = {1}
    for k in range(2, m):
        if m % k == 0: ka_vals.add(k)
        elif _coprime(k, m): ka_vals.add(k)

    kb_vals = {1}
    for k in range(2, ell):
        if ell % k == 0: kb_vals.add(k)
        elif _coprime(k, ell): kb_vals.add(k)

    for (s1, s2) in seeds:
        # 1.1 Constant-Monomial Codes: A = 1 + y^a + y^b, B = 1 + x^c + x^d
        # Generate valid A forms
        A_forms = []
        for k in ka_vals:
            e1, e2 = (k * s1) % m, (k * s2) % m
            if e1 != 0 and e2 != 0 and e1 != e2:
                A_forms.append([(0,0), (0,e1), (0,e2)])

        # Generate valid B forms
        B_forms = []
        for k in kb_vals:
            e1, e2 = (k * s1) % ell, (k * s2) % ell
            if e1 != 0 and e2 != 0 and e1 != e2:
                B_forms.append([(0,0), (e1,0), (e2,0)])

        # Pair them up
        for A in A_forms:
            for B in B_forms:
                _add(A, B)

        # 1.2 x/y-swap Codes: A = x^u + y^a + y^b, B = y^v + x^c + x^d
        # Use a broader set of scalings for mixed codes
        mixed_scalings = [1, 2, 3, 5]

        A_mixed_tails = []
        for k in mixed_scalings:
             e1, e2 = (k * s1) % m, (k * s2) % m
             if e1 != 0 and e2 != 0 and e1 != e2:
                 A_mixed_tails.append((e1, e2))

        B_mixed_tails = []
        for k in mixed_scalings:
             e1, e2 = (k * s1) % ell, (k * s2) % ell
             if e1 != 0 and e2 != 0 and e1 != e2:
                 B_mixed_tails.append((e1, e2))

        # Heads u (for A) and v (for B)
        # Often divisors of ell/m or small numbers
        u_vals = {1, 3}
        if ell % 2 == 0: u_vals.add(ell // 2)
        if ell % 3 == 0: u_vals.add(ell // 3)
        u_vals = sorted([u for u in u_vals if 0 < u < ell])

        v_vals = {1, 3}
        if m % 2 == 0: v_vals.add(m // 2)
        if m % 3 == 0: v_vals.add(m // 3)
        v_vals = sorted([v for v in v_vals if 0 < v < m])

        for u in u_vals:
            for (ae1, ae2) in A_mixed_tails:
                A = [(u, 0), (0, ae1), (0, ae2)]
                for v in v_vals:
                    for (be1, be2) in B_mixed_tails:
                        B = [(0, v), (be1, 0), (be2, 0)]
                        _add(A, B)

    # -----------------------------------------------------------------------
    # Strategy 2: Explicit Symmetric Search (Doubling & Gaps)
    # Complements seeds by finding codes where A and B have different structures
    # e.g. A is doubling, B is gap.
    # -----------------------------------------------------------------------
    heads_a = sorted([x for x in range(1, ell) if _coprime(x, ell)])[:4] # First few coprimes
    heads_d = sorted([y for y in range(1, m) if _coprime(y, m)])[:4]

    # Generate tails for A (y-exponents)
    y_tails = []
    for b in range(1, m):
        if not _coprime(b, m) and b > 4: continue
        # Doubling
        c = (2 * b) % m
        if c != b and c != 0: y_tails.append((b, c))
        # Gaps - include larger gaps for codes like [[288,32,20]]
        for g in [1, 2, 3, 5, 7, 8, 10]:
            c = (b + g) % m
            if c != b and c != 0: y_tails.append((b, c))

    # Generate tails for B (x-exponents)
    x_tails = []
    for e in range(1, ell):
        if not _coprime(e, ell) and e > 4: continue
        # Doubling
        f = (2 * e) % ell
        if f != e and f != 0: x_tails.append((e, f))
        # Gaps
        for g in [1, 2, 3, 5, 7, 10]:
            f = (e + g) % ell
            if f != e and f != 0: x_tails.append((e, f))

    # Limit tails to distinct sorted list, take top N to control count
    y_tails = sorted(list(set(y_tails)))[:40]
    x_tails = sorted(list(set(x_tails)))[:40]

    # Pair them
    for a in heads_a:
        for (b, c) in y_tails:
            A = [(a, 0), (0, b), (0, c)]
            for d in heads_d:
                for (e, f) in x_tails:
                    B = [(0, d), (e, 0), (f, 0)]
                    _add(A, B)

    # -----------------------------------------------------------------------
    # Strategy 3: Perturbations of Known Good Codes
    # -----------------------------------------------------------------------
    for code_spec in KNOWN_CODES:
        if code_spec["ell"] == ell and code_spec["m"] == m:
            base_A = code_spec["A_terms"]
            base_B = code_spec["B_terms"]
            _add(base_A, base_B)

            for delta in [-1, 1]:
                # Perturb A
                for i in range(len(base_A)):
                    if base_A[i] == (0,0): continue
                    new_A = list(base_A)
                    x, y = new_A[i]
                    if x > 0: x = (x + delta) % ell
                    if y > 0: y = (y + delta) % m
                    new_A[i] = (x, y)
                    if len(set(new_A)) == 3:
                        _add(new_A, base_B)

                # Perturb B
                for i in range(len(base_B)):
                    if base_B[i] == (0,0): continue
                    new_B = list(base_B)
                    x, y = new_B[i]
                    if x > 0: x = (x + delta) % ell
                    if y > 0: y = (y + delta) % m
                    new_B[i] = (x, y)
                    if len(set(new_B)) == 3:
                        _add(base_A, new_B)

    # -----------------------------------------------------------------------
    # Strategy 4: Cross-Lattice Reuse of Known Good Polynomials
    # -----------------------------------------------------------------------
    for code_spec in KNOWN_CODES:
        if code_spec["ell"] != ell or code_spec["m"] != m:
            base_A = code_spec["A_terms"]
            base_B = code_spec["B_terms"]
            fits = all(ax < ell and ay < m for ax, ay in base_A) and \
                   all(bx < ell and by < m for bx, by in base_B)
            if fits:
                _add(base_A, base_B)

    return candidates
