def generate_candidates(
    ell: int, m: int
) -> list[tuple[list[tuple[int, int]], list[tuple[int, int]]]]:
    """Generate candidate (A_terms, B_terms) pairs for given lattice dimensions."""
    candidates = []
    seen = set()

    def _add(a_terms, b_terms):
        """Add candidate if not a duplicate."""
        key = (tuple(sorted(a_terms)), tuple(sorted(b_terms)))
        if key not in seen:
            seen.add(key)
            candidates.append((list(a_terms), list(b_terms)))

    def _gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def _coprime(a, n):
        return _gcd(a, n) == 1

    def _get_factors(n):
        return [i for i in range(1, n + 1) if n % i == 0]

    # -----------------------------------------------------------------------
    # Strategy 1: Linked Constant-Monomial Codes (Targeting High k)
    # A = 1 + y^a + y^b, B = 1 + x^c + x^d
    # -----------------------------------------------------------------------

    # Generate A candidates (y-side)
    # Use strides that include factors of m (critical for high k) and coprimes
    strides_y = sorted(list(set([1] + _get_factors(m) + list(range(2, min(m, 9))))))

    A_seeds = []
    for s in strides_y:
        # Doubling: 1 + y^s + y^2s
        t2 = (2*s)%m
        if t2 != 0 and t2 != s: A_seeds.append([(0,0), (0,s), (0,t2)])
        # Tripling: 1 + y^s + y^3s
        t3 = (3*s)%m
        if t3 != 0 and t3 != s: A_seeds.append([(0,0), (0,s), (0,t3)])
        # Magic Gaps (non-consecutive)
        for g in [1, 2, 3, 5, 7, 8, 10]:
            t = (s+g)%m
            if t != 0 and t != s: A_seeds.append([(0,0), (0,s), (0,t)])

    # Deduplicate A seeds
    unique_A = []
    seen_A = set()
    for A in A_seeds:
        k = tuple(sorted(A))
        if k not in seen_A:
            seen_A.add(k)
            unique_A.append(A)

    # Rank A candidates by spread to avoid clustering
    def _spread_score(A):
        ys = sorted(t[1] for t in A)
        gaps = sorted([(ys[1]-ys[0])%m, (ys[2]-ys[1])%m, (ys[0]-ys[2])%m])
        return min(gaps) # Maximize the minimum gap

    unique_A.sort(key=_spread_score, reverse=True)
    unique_A = unique_A[:120] # Keep manageable count

    # Generate B candidates (x-side) linked to A
    strides_x = sorted(list(set([1] + _get_factors(ell) + list(range(2, min(ell, 13))))))

    for A in unique_A:
        exps = sorted([t[1] for t in A]) # [0, a, b]

        # Link Type 1: Algebraic Scaling B(x) = A(x^k)
        for k in strides_x:
            b_exps = [(e * k) % ell for e in exps]
            if len(set(b_exps)) == 3:
                B = [(e, 0) for e in b_exps]
                _add(A, B)

        # Link Type 2: Independent Structure on B
        # If we didn't find enough matches, try independent doubling/tripling
        if len(candidates) > 10000: continue

        for k in strides_x[:8]: # Limit independent search
            # Doubling
            f = (2*k)%ell
            if f!=k and f!=0: _add(A, [(0,0), (k,0), (f,0)])
            # Tripling
            f = (3*k)%ell
            if f!=k and f!=0: _add(A, [(0,0), (k,0), (f,0)])

    # -----------------------------------------------------------------------
    # Strategy 2: Coprime x/y-swap Symmetric Codes (Targeting Distance)
    # A = x^a + y^b + y^c, B = y^d + x^e + x^f
    # -----------------------------------------------------------------------

    # Heads: a and d
    a_vals = [1, 3] if ell > 3 else [1]
    if ell % 2 == 0: a_vals.append(ell//2 - 1)

    d_vals = [1, 3] if m > 3 else [1]
    if m % 2 == 0: d_vals.append(m//2 - 1)

    # Tails: y^b+y^c. Bias towards coprime b
    y_tails = []
    b_cands = [b for b in range(1, m) if _coprime(b, m)]
    for b in b_cands:
        # Doubling/Tripling
        for mult in [2, 3]:
            c = (mult*b)%m
            if c!=0 and c!=b: y_tails.append([(0,b), (0,c)])
        # Magic Gaps
        for g in [1, 2, 3, 5, 7]:
            c = (b+g)%m
            if c!=0 and c!=b: y_tails.append([(0,b), (0,c)])

    y_tails = [list(x) for x in set(tuple(sorted(t)) for t in y_tails)]
    y_tails = y_tails[:50]

    # Tails: x^e+x^f. Bias towards coprime e
    x_tails = []
    e_cands = [e for e in range(1, ell) if _coprime(e, ell)]
    for e in e_cands:
        # Doubling/Tripling
        for mult in [2, 3]:
            f = (mult*e)%ell
            if f!=0 and f!=e: x_tails.append([(e,0), (f,0)])
        # Magic Gaps
        for g in [1, 2, 5]:
            f = (e+g)%ell
            if f!=0 and f!=e: x_tails.append([(e,0), (f,0)])

    x_tails = [list(x) for x in set(tuple(sorted(t)) for t in x_tails)]
    x_tails = x_tails[:50]

    # Cartesian Product
    for a in a_vals:
        for d in d_vals:
            for y_tail in y_tails:
                A = [(a,0)] + y_tail
                for x_tail in x_tails:
                    B = [(0,d)] + x_tail
                    _add(A, B)
                    if len(candidates) > 12000: break
                if len(candidates) > 12000: break
            if len(candidates) > 12000: break
        if len(candidates) > 12000: break

    # -----------------------------------------------------------------------
    # Strategy 3: Perturbations & Reuse
    # -----------------------------------------------------------------------
    for code_spec in KNOWN_CODES:
        base_A = code_spec["A_terms"]
        base_B = code_spec["B_terms"]

        # 3a. Exact match + Perturbation
        if code_spec["ell"] == ell and code_spec["m"] == m:
            _add(base_A, base_B)
            # Perturb by ±1
            for delta in [-1, 1]:
                # Perturb A
                for i in range(len(base_A)):
                    if base_A[i] == (0,0): continue
                    new_A = list(base_A)
                    x, y = new_A[i]
                    if x > 0: x = (x + delta) % ell
                    if y > 0: y = (y + delta) % m
                    new_A[i] = (x, y)
                    if len(set(new_A)) == 3:
                        _add(new_A, base_B)
                # Perturb B
                for i in range(len(base_B)):
                    if base_B[i] == (0,0): continue
                    new_B = list(base_B)
                    x, y = new_B[i]
                    if x > 0: x = (x + delta) % ell
                    if y > 0: y = (y + delta) % m
                    new_B[i] = (x, y)
                    if len(set(new_B)) == 3:
                        _add(base_A, new_B)

        # 3b. Cross-Lattice Reuse
        else:
            fits_A = all(ax < ell and ay < m for ax, ay in base_A)
            fits_B = all(bx < ell and by < m for bx, by in base_B)
            if fits_A and fits_B:
                _add(base_A, base_B)

    return candidates
